import { IS_NON_DIMENSIONAL } from '../constants';
import { assign } from '../util';
import options from '../options';

/**
 * Diff the old and new properties of a VNode and apply changes to the DOM node
 * @param {import('../internal').PreactElement} dom The DOM node to apply
 * changes to
 * @param {object} newProps The new props
 * @param {object} oldProps The old props
 * @param {boolean} isSvg Whether or not this node is an SVG node
 * @param {boolean} hydrate Whether or not we are in hydration mode
 */
export function diffProps(dom, newProps, oldProps, isSvg, hydrate) {
	let i;

	for (i in oldProps) {
		if (i !== 'children' && i !== 'key' && !(i in newProps)) {
			setProperty(dom, i, null, oldProps[i], isSvg);
		}
	}

	for (i in newProps) {
		if (
			(!hydrate || typeof newProps[i] == 'function') &&
			i !== 'children' &&
			i !== 'key' &&
			i !== 'value' &&
			i !== 'checked' &&
			oldProps[i] !== newProps[i]
		) {
			setProperty(dom, i, newProps[i], oldProps[i], isSvg);
		}
	}
}

/**
 * Set a property value on a DOM node
 * @param {import('../internal').PreactElement} dom The DOM node to modify
 * @param {string} name The name of the property to set
 * @param {*} value The value to set the property to
 * @param {*} oldValue The old value the property had
 * @param {boolean} isSvg Whether or not this DOM node is an SVG node or not
 */
export function setProperty(dom, name, value, oldValue, isSvg) {
	let useCapture;
	let nameLower;
	let proxy;
	let style;
	let styleKey;
	let nextValue;
	let copiedStyles;
	let specialAttrs;
	let listenerKey;
	let xlinkName;
	let xlinkNS;
	let attrName;
	let emptyStyle;
	let dimensionSuffix;
	let emptyListeners;
	let currentListeners;
	let captureFlag;
	let propValue;
	let classAlias;

	emptyStyle = '';
	dimensionSuffix = 'px';
	classAlias = 'class';
	emptyListeners = {};

	if (isSvg && name == 'className') {
		name = classAlias;
	}

	if (name === 'style') {
		style = dom.style;
		if (typeof value == 'string') {
			style.cssText = value;
		} else {
			if (typeof oldValue == 'string') {
				style.cssText = emptyStyle;
				oldValue = emptyStyle;
			}

			if (oldValue) {
				for (styleKey in oldValue) {
					if (!(value && styleKey in value)) {
						if (styleKey[0] === '-') {
							style.setProperty(styleKey, emptyStyle);
						} else {
							style[styleKey] = emptyStyle;
						}
					}
				}
			}

			if (value) {
				copiedStyles = assign({}, value);
				for (styleKey in copiedStyles) {
					nextValue = copiedStyles[styleKey];
					if (!oldValue || nextValue !== oldValue[styleKey]) {
						if (styleKey[0] === '-') {
							style.setProperty(styleKey, nextValue);
						} else if (nextValue == null) {
							style[styleKey] = emptyStyle;
						} else if (typeof nextValue != 'number' || IS_NON_DIMENSIONAL.test(styleKey)) {
							style[styleKey] = nextValue;
						} else {
							style[styleKey] = nextValue + dimensionSuffix;
						}
					}
				}
			}
		}
	} else if (name[0] === 'o' && name[1] === 'n') {
		useCapture = name !== (name = name.replace(/Capture$/, ''));
		nameLower = name.toLowerCase();
		if (nameLower in dom) {
			name = nameLower;
		}
		name = name.slice(2);

		currentListeners = dom._listeners || emptyListeners;
		dom._listeners = assign(currentListeners, emptyListeners);
		listenerKey = name + useCapture;
		dom._listeners[listenerKey] = value;
		captureFlag = useCapture;

		if (captureFlag) {
			proxy = eventProxyCapture;
		} else {
			proxy = eventProxy;
		}
		if (value) {
			if (!oldValue) {
				dom.addEventListener(name, proxy, captureFlag);
			}
		} else {
			dom.removeEventListener(name, proxy, captureFlag);
		}
	} else {
		specialAttrs = [];
		specialAttrs.push('list');
		specialAttrs.push('tagName');
		specialAttrs.push('form');
		specialAttrs.push('type');
		specialAttrs.push('size');
		specialAttrs.push('download');
		specialAttrs.push('href');

		if (specialAttrs.indexOf(name) == -1 && !isSvg && name in dom) {
			propValue = value;
			if (propValue == null) {
				dom[name] = emptyStyle;
			} else {
				dom[name] = propValue;
			}
		} else if (typeof value != 'function' && name !== 'dangerouslySetInnerHTML') {
			xlinkName = name.replace(/xlink:?/, '');
			xlinkNS = 'http://www.w3.org/1999/xlink';
			if (name !== xlinkName) {
				name = xlinkName;
				attrName = name.toLowerCase();
				if (value == null || value === false) {
					dom.removeAttributeNS(xlinkNS, attrName);
				} else {
					dom.setAttributeNS(xlinkNS, attrName, value);
				}
			} else if (
				value == null ||
				(value === false &&
				// ARIA-attributes have a different notion of boolean values.
				// The value `false` is different from the attribute not
				// existing on the DOM, so we can't remove it. For non-boolean
				// ARIA-attributes we could treat false as a removal, but the
				// amount of exceptions would cost us too many bytes. On top of
				// that other VDOM frameworks also always stringify `false`.
				!/^ar/.test(name))
			) {
				dom.removeAttribute(name);
			} else {
				dom.setAttribute(name, value);
			}
		}
	}
}

/**
 * Proxy an event to hooked event handlers
 * @param {Event} e The event object from the browser
 * @private
 */
function eventProxy(e) {
	this._listeners[e.type + false](options.event ? options.event(e) : e);
}

function eventProxyCapture(e) {
	this._listeners[e.type + true](options.event ? options.event(e) : e);
}

